 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    panel_cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    r0, r1 = min(r for r, c in panel_cells), max(r for r, c in panel_cells)
    c0, c1 = min(c for r, c in panel_cells), max(c for r, c in panel_cells)
    panel = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]

    outside = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 1) and not (r0 <= r <= r1 and c0 <= c <= c1)]
    labels = {v for _, _, v in outside}
    # Three matching color markers specify the desired corner arrangement.
    target = {}
    ar0, ar1 = min(r for r, c, v in outside), max(r for r, c, v in outside)
    ac0, ac1 = min(c for r, c, v in outside), max(c for r, c, v in outside)
    for r, c, v in outside:
        target[v] = (0 if r - ar0 <= ar1 - r else 1,
                     0 if c - ac0 <= ac1 - c else 1)

    def corners(g):
        pts = [(r, c, g[r][c]) for r in range(len(g)) for c in range(len(g[0])) if g[r][c] in labels]
        rr0, rr1 = min(r for r, c, v in pts), max(r for r, c, v in pts)
        cc0, cc1 = min(c for r, c, v in pts), max(c for r, c, v in pts)
        return {v: (0 if r - rr0 <= rr1 - r else 1,
                    0 if c - cc0 <= cc1 - c else 1) for r, c, v in pts}

    def cw(g):
        return [list(row) for row in zip(*g[::-1])]

    candidates = []
    for reflected in (False, True):
        g = [row[::-1] for row in panel] if reflected else [row[:] for row in panel]
        for _ in range(4):
            candidates.append(g)
            g = cw(g)
    for g in candidates:
        if corners(g) == target:
            return g
    # The external corner key is expected to uniquely determine an orientation.
    return panel
